select distinct id,indexName from ( select ID id, index_name indexName from REP_INDEX_PRIMARY where 1=1 and ID in
#{id}
and is_quote = '01' /*被引用*/ union all select sub.ID id, sub.index_value indexName from REP_INDEX_SUB sub left join REP_INDEX_PRIMARY pri on sub.pri_id = pri.id where 1=1 and sub.id in
#{id}
and pri.is_quote = '01' /*被引用*/ )

select * from REP_INDEX_SUB r1 where r1.PRI_ID = #{priId,jdbcType=VARCHAR}

    and r1.id !=#{id,jdbcType=VARCHAR}

AND ((r1.INDEX_DATE <= #{indexDate,jdbcType=DATE} and r1.end_date >= #{indexDate,jdbcType=DATE}) or
(r1.INDEX_DATE <= #{endDate,jdbcType=DATE} and r1.end_date >= #{endDate,jdbcType=DATE})
or (#{indexDate,jdbcType=DATE} <= r1.INDEX_DATE and  #{endDate,jdbcType=DATE} >=r1.end_date)
)

select * from REP_INDEX_SUB
where 1=1

	and PRI_ID = #{priId,jdbcType=VARCHAR}


	and INDEX_TYPE = #{indexType,jdbcType=VARCHAR}


	and AUDIT_STATUS = #{auditStatus,jdbcType=VARCHAR}


	and INDEX_YEAR = #{indexYear,jdbcType=VARCHAR}


	and INDEX_PERIOD = #{indexPeriod,jdbcType=VARCHAR}


	and id != #{id,jdbcType=VARCHAR}

